// Builds dist/data/ballistics.js: every projectile record of the wiki attack datamine
// (db/source/weapons_data.json) with what range falloff and drop need, and the four
// angle penetration values of its damage. Do not edit the output.
// Usage: node scripts/build-ballistics.mjs
import { readFile, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const source = JSON.parse(await readFile(new URL('../db/source/weapons_data.json', import.meta.url), 'utf8'));
const { projectile, damage, explosion } = source.data;
// Fragments and bomblets: the projectiles an explosion throws out (its shrapnel), not ones a weapon fires.
const thrown = new Set(Object.values(explosion).map(record => record.shrapnel).filter(Boolean));
const num = value => (Number.isFinite(value) ? Number(value.toFixed(4)) : null);

// Stratagem guns the datamine has no projectile for (user request 2026-11-26): the round of their game data sheet entry
// (db/source/game_sheets/weapons.json, by designation), under '<designation>_P', marked source 'game'. The sheet's
// lifetime column is nearly always 0, so these get no lifetime.
const SHEET_GUNS = ['E/MG-101', 'E/AT-12'];
const sheet = JSON.parse(await readFile(new URL('../db/source/game_sheets/weapons.json', import.meta.url), 'utf8')).무기;
const sheetRounds = Object.fromEntries(SHEET_GUNS.map(code => {
  const rounds = [...new Set(sheet.filter(g => g.코드 === code && g.투사체).map(g => JSON.stringify(g.투사체)))].map(r => JSON.parse(r));
  if (rounds.length !== 1) throw new Error(`${code}: ${rounds.length} different game sheet rounds`);
  const r = rounds[0];
  return [`${code}_P`, { velocity: num(r.속도), caliber: num(r.구경), mass: num(r.질량), drag: num(r.항력), gravity: num(r.중력_배율), lifetime: 0,
    pellets: num(r.탄_수), ap: r.피해.관통.map(num), source: 'game' }];
}));

export const projectileBallistics = Object.fromEntries([...Object.entries(projectile).map(([key, record]) => {
  const hit = damage[record.damage_id];
  return [key, {
    velocity: num(record.velocity), caliber: num(record.caliber), mass: num(record.mass), drag: num(record.drag),
    gravity: num(record.gravity), lifetime: num(record.lifetime), pellets: num(record.pellets),
    ap: hit ? [hit.ap1, hit.ap2, hit.ap3, hit.ap4].map(num) : null,
    ...(thrown.has(key) && { thrown: true }),
  }];
}), ...Object.entries(sheetRounds)]);

const out = `// Generated by scripts/build-ballistics.mjs from db/source/weapons_data.json. Do not edit.
// Projectile records of the wiki attack datamine: muzzle velocity (m/s), caliber (mm), mass (g),
// drag coefficient, gravity multiplier, lifetime (s, 0 = no limit), pellets, and the penetration
// at the four impact angles (under 25, 26-60, 61-80 and 81-90 degrees); thrown = a fragment or bomblet an explosion
// throws out rather than a projectile a weapon fires; source 'game' = from the game data sheet (E/MG-101, E/AT-12).
export const ballisticsSource = ${JSON.stringify({ source: source.source, revision: source.revision, checkedAt: source.retrievedAt })};
export const projectileBallistics = {
${Object.entries(projectileBallistics).map(([key, value]) => `  ${JSON.stringify(key)}: ${JSON.stringify(value)},`).join('\n')}
};
`;
if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  await writeFile(new URL('../dist/data/ballistics.js', import.meta.url), out);
  console.log(`${Object.keys(projectileBallistics).length} projectile records`);
}
export const ballisticsOutput = out;
